changeSet.sql:
declare
    d_exists number;
begin
    select 1 into d_exists from REGISTRO
    where CHIAVE = 'PRODUCTS/AD4' and STRINGA = 'TracciaDirittiAccesso';

    update REGISTRO set VALORE = 'SI'
    where CHIAVE = 'PRODUCTS/AD4' and STRINGA = 'TracciaDirittiAccesso';
exception
    when no_data_found then
        insert into REGISTRO (CHIAVE, STRINGA, COMMENTO, VALORE)
        values ('PRODUCTS/AD4',
                'TracciaDirittiAccesso',
                'Indica se tenere traccia delle modifiche nelle assegnazioni dei diritti di accesso. (Valori possibili: SI/NO - default: NO)',
                'SI');
end;
